//! Golden-vector test for the `gitobj` module: `tests/golden/gitobj.json` per
//! VECTORS.md, generated by the Go implementation.

mod common;

use amber_store_core::gitobj;

#[derive(serde::Deserialize)]
struct GitFile {
    cases: Vec<Case>,
}

#[derive(serde::Deserialize)]
struct LinkCase {
    key: String,
    leaf: bool,
}

#[derive(serde::Deserialize)]
struct Case {
    name: String,
    data_hex: String,
    #[serde(default)]
    key: Option<String>,
    #[serde(default)]
    key_error: Option<String>,
    links: Vec<LinkCase>,
    #[serde(default)]
    links_error: Option<String>,
}

#[test]
fn golden_gitobj() {
    let Some(bytes) = common::load("gitobj.json") else {
        return;
    };
    let file: GitFile = serde_json::from_slice(&bytes).expect("gitobj.json parses");
    assert!(!file.cases.is_empty(), "gitobj.json has no cases");
    for c in &file.cases {
        let data = hex::decode(&c.data_hex).expect("data_hex");
        let name = &c.name;

        match gitobj::key_of(&data) {
            Ok(k) => {
                assert_eq!(Some(k.to_string()).as_ref(), c.key.as_ref(), "{name}: key");
                assert!(c.key_error.is_none(), "{name}: Go has no key");
                assert_eq!(k.validate(), Ok(()), "{name}");
            }
            Err(e) => assert_eq!(Some(e.to_string()).as_ref(), c.key_error.as_ref(), "{name}"),
        }

        match gitobj::links(&data) {
            Ok(links) => {
                assert!(
                    c.links_error.is_none(),
                    "{name}: Go says {:?}",
                    c.links_error
                );
                let got: Vec<(String, bool)> =
                    links.iter().map(|l| (l.key.to_string(), l.leaf)).collect();
                let want: Vec<(String, bool)> =
                    c.links.iter().map(|l| (l.key.clone(), l.leaf)).collect();
                assert_eq!(got, want, "{name}: links");
            }
            Err(e) => assert_eq!(
                Some(e.to_string()).as_ref(),
                c.links_error.as_ref(),
                "{name}: error text"
            ),
        }
    }
}
